INSERT
  INTO
	   TRACKING_SESSION (
						  SESSION_ID
						, ROOM_ID
						, PARTICIPANT_ID
						, DEVICE_KEY
						, DEST_LAT
						, DEST_LNG
						)
VALUES
	   (
		 SEQ_TRACKING_SESSION.NEXTVAL
	   , #{roomId}
	   , #{participantId}
	   , #{deviceKey}
	   , #{destLat}
	   , #{destLng}
	   )

INSERT
  INTO
	   LOCATION_LOG (
					  LOG_ID
					, SESSION_ID
					, SEQ
					, LAT
					, LNG
					, DISTANCE_M
					)
VALUES
	   (
		 SEQ_LOCATION_LOG.NEXTVAL
	   , #{sessionId}
	   , #{seq}
	   , #{lat}
	   , #{lng}
	   , #{distanceM}
	   )
